-- SpazaStock shared D1 database: identity, shops, membership, catalog, plans, notifications, administration.
-- Generated by `npm run data:schema` from supabase/migrations. Do not edit by hand before the
-- cutover: change the generator or partition.ts and regenerate. After cutover this file is frozen
-- and later changes go in new migrations.
-- Shop ledgers (products, stock, sales, alerts, wholesale) live in each shop's Durable Object instead.

CREATE TABLE users (
  id TEXT NOT NULL,
  email TEXT NOT NULL,
  password_hash TEXT,
  password_kind TEXT CHECK (password_kind IN ('bcrypt', 'pbkdf2')),
  email_confirmed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  last_sign_in_at TEXT,
  metadata TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY (id),
  CHECK ((password_hash IS NULL) = (password_kind IS NULL)),
  CHECK (email = lower(trim(email)))
) STRICT;
CREATE UNIQUE INDEX users_email_key ON users (email);

CREATE TABLE entitlement_catalog (
  key TEXT NOT NULL,
  kind TEXT NOT NULL,
  description TEXT NOT NULL,
  PRIMARY KEY (key),
  CHECK ((kind IN ('boolean', 'limit')))
) STRICT;

CREATE TABLE platform_admins (
  user_id TEXT NOT NULL,
  role TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  granted_by TEXT,
  granted_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  revoked_by TEXT,
  revoked_at TEXT,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (user_id),
  FOREIGN KEY (granted_by) REFERENCES users (id) ON DELETE SET NULL,
  FOREIGN KEY (revoked_by) REFERENCES users (id) ON DELETE SET NULL,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CHECK (((status = 'revoked') = (revoked_at IS NOT NULL))),
  CHECK ((role IN ('superadmin', 'support', 'billing', 'analyst'))),
  CHECK ((status IN ('active', 'revoked')))
) STRICT;
CREATE INDEX platform_admins_granted_by_idx ON platform_admins (granted_by);
CREATE INDEX platform_admins_revoked_by_idx ON platform_admins (revoked_by);
CREATE TRIGGER platform_admins_set_updated_at AFTER UPDATE ON platform_admins FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE platform_admins SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE platform_role_permissions (
  role TEXT NOT NULL,
  permission TEXT NOT NULL,
  PRIMARY KEY (role, permission),
  CHECK ((role IN ('superadmin', 'support', 'billing', 'analyst')))
) STRICT;

CREATE TABLE role_permissions (
  role TEXT NOT NULL,
  permission TEXT NOT NULL,
  PRIMARY KEY (role, permission),
  CHECK ((role IN ('owner', 'manager', 'staff')))
) STRICT;

CREATE TABLE catalog_products (
  id TEXT NOT NULL,
  name TEXT NOT NULL,
  brand TEXT,
  category TEXT NOT NULL,
  package_size TEXT,
  package_quantity REAL,
  package_unit TEXT,
  image_url TEXT,
  ingredients TEXT,
  source TEXT NOT NULL,
  verification_status TEXT NOT NULL,
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  image_path TEXT,
  common INTEGER NOT NULL DEFAULT 0 CHECK (common IN (0, 1)),
  PRIMARY KEY (id),
  FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CHECK (((brand IS NULL) OR ((length(trim(brand)) >= 1) AND (length(trim(brand)) <= 80)))),
  CHECK ((category IN ('groceries', 'beverages', 'snacks', 'bakery', 'dairy', 'personal_care', 'household', 'airtime', 'other'))),
  CHECK (((ingredients IS NULL) OR ((length(trim(ingredients)) >= 1) AND (length(trim(ingredients)) <= 4000)))),
  CHECK (((length(trim(name)) >= 1) AND (length(trim(name)) <= 200))),
  CHECK (((package_quantity IS NULL) OR (package_quantity > (0)))),
  CHECK (((package_size IS NULL) OR ((length(trim(package_size)) >= 1) AND (length(trim(package_size)) <= 40)))),
  CHECK (((package_unit IS NULL) OR ((length(trim(package_unit)) >= 1) AND (length(trim(package_unit)) <= 16)))),
  CHECK ((source IN ('open_food_facts', 'user'))),
  CHECK ((verification_status IN ('external', 'user_submitted', 'verified')))
) STRICT;
CREATE INDEX catalog_products_common_category_name_idx ON catalog_products (category, name, id) WHERE common;
CREATE INDEX catalog_products_common_name_idx ON catalog_products (name, id) WHERE common;
CREATE INDEX catalog_products_updated_idx ON catalog_products (updated_at);
CREATE TRIGGER catalog_products_set_updated_at AFTER UPDATE ON catalog_products FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE catalog_products SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE membership_events (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  member_id TEXT NOT NULL,
  actor_id TEXT,
  target_user_id TEXT,
  target_email TEXT,
  action TEXT NOT NULL,
  old_role TEXT,
  new_role TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  CHECK ((action IN ('invited', 'invite_resent', 'invite_revoked', 'joined', 'role_changed', 'deactivated', 'reactivated', 'removed')))
) STRICT;
CREATE INDEX membership_events_shop_created_idx ON membership_events (shop_id, created_at DESC);

CREATE TABLE plans (
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  price_cents INTEGER,
  currency TEXT NOT NULL DEFAULT 'ZAR',
  billing_interval TEXT NOT NULL DEFAULT 'month',
  trial_days INTEGER NOT NULL DEFAULT 0,
  grace_days INTEGER NOT NULL DEFAULT 7,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (code),
  CHECK ((billing_interval IN ('month', 'year'))),
  CHECK (((grace_days >= 0) AND (grace_days <= 90))),
  CHECK (((length(trim(name)) >= 1) AND (length(trim(name)) <= 80))),
  CHECK (((price_cents IS NULL) OR ((price_cents >= 0) AND (price_cents <= 100000000)))),
  CHECK (((trial_days >= 0) AND (trial_days <= 365)))
) STRICT;
CREATE TRIGGER plans_set_updated_at AFTER UPDATE ON plans FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE plans SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE platform_audit_log (
  id INTEGER NOT NULL,
  occurred_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  actor_id TEXT,
  actor_email TEXT,
  actor_role TEXT,
  action TEXT NOT NULL,
  target_type TEXT,
  target_id TEXT,
  shop_id TEXT,
  reason TEXT,
  outcome TEXT NOT NULL,
  details TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY (id),
  CHECK (((actor_email IS NULL) OR (length(actor_email) <= 320))),
  CHECK (((actor_role IS NULL) OR (length(actor_role) <= 40))),
  CHECK ((outcome IN ('success', 'denied'))),
  CHECK (((reason IS NULL) OR (length(reason) <= 500))),
  CHECK (((target_id IS NULL) OR (length(target_id) <= 200))),
  CHECK (((target_type IS NULL) OR (target_type IN ('shop', 'user', 'admin', 'plan', 'feature', 'subscription', 'platform', 'catalog'))))
) STRICT;
CREATE INDEX platform_audit_log_action_idx ON platform_audit_log (action, occurred_at DESC);
CREATE INDEX platform_audit_log_actor_idx ON platform_audit_log (actor_id, occurred_at DESC);
CREATE INDEX platform_audit_log_occurred_idx ON platform_audit_log (occurred_at DESC);
CREATE INDEX platform_audit_log_shop_idx ON platform_audit_log (shop_id, occurred_at DESC);
CREATE INDEX platform_audit_log_target_idx ON platform_audit_log (target_id);
CREATE TRIGGER platform_audit_log_reject_update BEFORE UPDATE ON platform_audit_log BEGIN SELECT RAISE(ABORT, 'platform_audit_log is append-only'); END;
CREATE TRIGGER platform_audit_log_reject_delete BEFORE DELETE ON platform_audit_log BEGIN SELECT RAISE(ABORT, 'platform_audit_log is append-only'); END;

CREATE TABLE product_lookup_cache (
  barcode TEXT NOT NULL,
  status TEXT NOT NULL,
  payload TEXT,
  provider TEXT NOT NULL DEFAULT 'open_food_facts',
  fetched_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  expires_at TEXT NOT NULL,
  PRIMARY KEY (barcode),
  CHECK ((((status = 'not_found') AND (payload IS NULL)) OR ((status = 'found') AND (payload IS NOT NULL)))),
  CHECK ((status IN ('found', 'not_found')))
) STRICT;
CREATE INDEX product_lookup_cache_expires_at_idx ON product_lookup_cache (expires_at);

CREATE TABLE profiles (
  id TEXT NOT NULL,
  display_name TEXT,
  phone TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (id) REFERENCES users (id) ON DELETE CASCADE,
  CHECK (((display_name IS NULL) OR ((length(trim(display_name)) >= 1) AND (length(trim(display_name)) <= 80))))
) STRICT;
CREATE TRIGGER profiles_set_updated_at AFTER UPDATE ON profiles FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE profiles SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE push_subscriptions (
  id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  endpoint TEXT NOT NULL,
  p256dh TEXT NOT NULL,
  auth TEXT NOT NULL,
  user_agent TEXT,
  failure_count INTEGER NOT NULL DEFAULT 0,
  last_success_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CHECK (((length(auth) >= 8) AND (length(auth) <= 100))),
  CHECK ((((length(endpoint) >= 12) AND (length(endpoint) <= 1000)) AND (endpoint  LIKE  'https://%'))),
  CHECK ((failure_count >= 0)),
  CHECK (((length(p256dh) >= 20) AND (length(p256dh) <= 200))),
  CHECK (((user_agent IS NULL) OR (length(user_agent) <= 300)))
) STRICT;
CREATE UNIQUE INDEX push_subscriptions_endpoint_key ON push_subscriptions (endpoint);
CREATE INDEX push_subscriptions_user_id_idx ON push_subscriptions (user_id);
CREATE TRIGGER push_subscriptions_set_updated_at AFTER UPDATE ON push_subscriptions FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE push_subscriptions SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE shops (
  id TEXT NOT NULL,
  owner_id TEXT NOT NULL,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  timezone TEXT NOT NULL DEFAULT 'Africa/Johannesburg',
  expiry_reminder_days TEXT NOT NULL DEFAULT '[21,14,7]',
  status TEXT NOT NULL DEFAULT 'active',
  suspended_at TEXT,
  suspended_by TEXT,
  suspension_reason TEXT,
  phone TEXT,
  address TEXT,
  city TEXT,
  province TEXT,
  latitude REAL,
  longitude REAL,
  catalog_prompt_pending INTEGER NOT NULL DEFAULT 0 CHECK (catalog_prompt_pending IN (0, 1)),
  PRIMARY KEY (id),
  FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE CASCADE,
  FOREIGN KEY (suspended_by) REFERENCES users (id) ON DELETE SET NULL,
  CHECK (((address IS NULL) OR ((length(address) >= 1) AND (length(address) <= 200)))),
  CHECK (((city IS NULL) OR ((length(city) >= 1) AND (length(city) <= 100)))),
  CHECK (((latitude IS NULL) OR ((latitude >= (-90)) AND (latitude <= (90))))),
  CHECK ((((latitude IS NULL) AND (longitude IS NULL)) OR ((latitude IS NOT NULL) AND (longitude IS NOT NULL)))),
  CHECK (((longitude IS NULL) OR ((longitude >= (-180)) AND (longitude <= (180))))),
  CHECK (((length(trim(name)) >= 1) AND (length(trim(name)) <= 120))),
  CHECK (((province IS NULL) OR (province IN ('EC', 'FS', 'GP', 'KZN', 'LP', 'MP', 'NC', 'NW', 'WC')))),
  CHECK ((status IN ('active', 'suspended'))),
  CHECK (((status = 'suspended') = (suspended_at IS NOT NULL))),
  CHECK (((suspension_reason IS NULL) OR (length(suspension_reason) <= 500)))
) STRICT;
CREATE INDEX shops_created_at_idx ON shops (created_at DESC);
CREATE INDEX shops_owner_id_idx ON shops (owner_id);
CREATE INDEX shops_status_created_idx ON shops (status, created_at DESC);
CREATE INDEX shops_suspended_by_idx ON shops (suspended_by);
CREATE TRIGGER shops_set_updated_at AFTER UPDATE ON shops FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE shops SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE subscription_events (
  id INTEGER NOT NULL,
  occurred_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  shop_id TEXT NOT NULL,
  subscription_id TEXT NOT NULL,
  actor_id TEXT,
  event TEXT NOT NULL,
  old_plan TEXT,
  new_plan TEXT,
  old_status TEXT,
  new_status TEXT,
  details TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY (id),
  CHECK ((event IN ('created', 'plan_changed', 'status_changed', 'updated')))
) STRICT;
CREATE INDEX subscription_events_occurred_idx ON subscription_events (occurred_at);
CREATE INDEX subscription_events_shop_idx ON subscription_events (shop_id, occurred_at DESC);
CREATE INDEX subscription_events_status_idx ON subscription_events (new_status, occurred_at);
CREATE TRIGGER subscription_events_reject_update BEFORE UPDATE ON subscription_events BEGIN SELECT RAISE(ABORT, 'subscription_events is append-only'); END;
CREATE TRIGGER subscription_events_reject_delete BEFORE DELETE ON subscription_events BEGIN SELECT RAISE(ABORT, 'subscription_events is append-only'); END;

CREATE TABLE catalog_barcodes (
  barcode TEXT NOT NULL,
  catalog_product_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  units_per_package INTEGER,
  source TEXT NOT NULL,
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (barcode),
  FOREIGN KEY (catalog_product_id) REFERENCES catalog_products (id) ON DELETE CASCADE,
  FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CHECK ((kind IN ('unit', 'alternate', 'pack'))),
  CHECK ((source IN ('open_food_facts', 'user'))),
  CHECK ((((kind = 'pack') AND ((units_per_package >= 2) AND (units_per_package <= 10000))) OR ((kind IN ('unit', 'alternate')) AND (units_per_package IS NULL))))
) STRICT;
CREATE INDEX catalog_barcodes_product_idx ON catalog_barcodes (catalog_product_id);
CREATE TRIGGER catalog_barcodes_set_updated_at AFTER UPDATE ON catalog_barcodes FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE catalog_barcodes SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE catalog_corrections (
  id TEXT NOT NULL,
  catalog_product_id TEXT NOT NULL,
  shop_id TEXT,
  proposed_name TEXT,
  proposed_brand TEXT,
  proposed_category TEXT,
  proposed_package_size TEXT,
  proposed_package_quantity REAL,
  proposed_package_unit TEXT,
  proposed_ingredients TEXT,
  proposed_image_url TEXT,
  reason TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  submitted_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (catalog_product_id) REFERENCES catalog_products (id) ON DELETE CASCADE,
  FOREIGN KEY (shop_id) REFERENCES shops (id) ON DELETE SET NULL,
  FOREIGN KEY (submitted_by) REFERENCES users (id) ON DELETE SET NULL,
  CHECK (((proposed_brand IS NULL) OR ((length(trim(proposed_brand)) >= 1) AND (length(trim(proposed_brand)) <= 80)))),
  CHECK (((proposed_category IS NULL) OR (proposed_category IN ('groceries', 'beverages', 'snacks', 'bakery', 'dairy', 'personal_care', 'household', 'airtime', 'other')))),
  CHECK (((proposed_ingredients IS NULL) OR ((length(trim(proposed_ingredients)) >= 1) AND (length(trim(proposed_ingredients)) <= 4000)))),
  CHECK (((proposed_name IS NULL) OR ((length(trim(proposed_name)) >= 1) AND (length(trim(proposed_name)) <= 200)))),
  CHECK (((proposed_package_quantity IS NULL) OR (proposed_package_quantity > (0)))),
  CHECK (((proposed_package_size IS NULL) OR ((length(trim(proposed_package_size)) >= 1) AND (length(trim(proposed_package_size)) <= 40)))),
  CHECK (((proposed_package_unit IS NULL) OR ((length(trim(proposed_package_unit)) >= 1) AND (length(trim(proposed_package_unit)) <= 16)))),
  CHECK (((length(trim(reason)) >= 1) AND (length(trim(reason)) <= 200))),
  CHECK ((status IN ('pending', 'applied', 'dismissed')))
) STRICT;
CREATE INDEX catalog_corrections_product_idx ON catalog_corrections (catalog_product_id, status);
CREATE TRIGGER catalog_corrections_set_updated_at AFTER UPDATE ON catalog_corrections FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE catalog_corrections SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE notifications (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  type TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT,
  data TEXT NOT NULL DEFAULT '{}',
  read_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  push_status TEXT NOT NULL DEFAULT 'skipped',
  push_attempts INTEGER NOT NULL DEFAULT 0,
  push_next_at TEXT,
  pushed_at TEXT,
  push_error TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id) REFERENCES shops (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CHECK (((body IS NULL) OR (length(body) <= 2000))),
  CHECK ((push_attempts >= 0)),
  CHECK (((push_error IS NULL) OR (length(push_error) <= 500))),
  CHECK ((push_status IN ('pending', 'sending', 'sent', 'failed', 'skipped'))),
  CHECK (((length(title) >= 1) AND (length(title) <= 200))),
  CHECK ((type IN ('low_stock', 'expiry', 'stock_discrepancy', 'member', 'system')))
) STRICT;
CREATE INDEX notifications_push_due_idx ON notifications (push_next_at) WHERE (push_status IN ('pending', 'sending'));
CREATE INDEX notifications_push_failed_idx ON notifications (updated_at) WHERE (push_status = 'failed');
CREATE INDEX notifications_shop_updated_idx ON notifications (shop_id, updated_at);
CREATE INDEX notifications_user_read_idx ON notifications (user_id, read_at);
CREATE TRIGGER notifications_set_updated_at AFTER UPDATE ON notifications FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE notifications SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE plan_entitlements (
  plan_code TEXT NOT NULL,
  key TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  limit_value INTEGER,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (plan_code, key),
  FOREIGN KEY (key) REFERENCES entitlement_catalog (key),
  FOREIGN KEY (plan_code) REFERENCES plans (code) ON UPDATE CASCADE ON DELETE CASCADE,
  CHECK (((limit_value IS NULL) OR ((limit_value >= 0) AND (limit_value <= 1000000))))
) STRICT;
CREATE INDEX plan_entitlements_key_idx ON plan_entitlements (key);
CREATE TRIGGER plan_entitlements_set_updated_at AFTER UPDATE ON plan_entitlements FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE plan_entitlements SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE platform_features (
  key TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  updated_by TEXT,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (key),
  FOREIGN KEY (key) REFERENCES entitlement_catalog (key),
  FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL
) STRICT;
CREATE INDEX platform_features_updated_by_idx ON platform_features (updated_by);
CREATE TRIGGER platform_features_set_updated_at AFTER UPDATE ON platform_features FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE platform_features SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE shop_members (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  user_id TEXT,
  invited_email TEXT,
  role TEXT NOT NULL,
  invited_by TEXT,
  joined_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  status TEXT NOT NULL DEFAULT 'active',
  deactivated_at TEXT,
  deactivated_by TEXT,
  invite_token_hash TEXT,
  invite_expires_at TEXT,
  invite_sent_at TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (deactivated_by) REFERENCES users (id) ON DELETE SET NULL,
  FOREIGN KEY (invited_by) REFERENCES users (id) ON DELETE SET NULL,
  FOREIGN KEY (shop_id) REFERENCES shops (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CHECK (((status = 'active') OR (user_id IS NOT NULL))),
  CHECK ((role IN ('owner', 'manager', 'staff'))),
  CHECK ((status IN ('active', 'deactivated'))),
  CHECK (((invite_token_hash IS NULL) OR (user_id IS NULL))),
  CHECK (((user_id IS NOT NULL) OR (invited_email IS NOT NULL)))
) STRICT;
CREATE INDEX shop_members_deactivated_by_idx ON shop_members (deactivated_by);
CREATE UNIQUE INDEX shop_members_invite_token_key ON shop_members (invite_token_hash) WHERE (invite_token_hash IS NOT NULL);
CREATE INDEX shop_members_invited_by_idx ON shop_members (invited_by);
CREATE INDEX shop_members_pending_email_idx ON shop_members (invited_email) WHERE (user_id IS NULL);
CREATE UNIQUE INDEX shop_members_pending_email_key ON shop_members (shop_id, invited_email) WHERE (user_id IS NULL);
CREATE INDEX shop_members_shop_updated_idx ON shop_members (shop_id, updated_at);
CREATE UNIQUE INDEX shop_members_shop_user_key ON shop_members (shop_id, user_id);
CREATE INDEX shop_members_user_id_idx ON shop_members (user_id);
CREATE TRIGGER shop_members_set_updated_at AFTER UPDATE ON shop_members FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE shop_members SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE subscriptions (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  plan TEXT NOT NULL DEFAULT 'free',
  status TEXT NOT NULL DEFAULT 'active',
  current_period_end TEXT,
  provider TEXT,
  provider_customer_id TEXT,
  provider_subscription_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  trial_ends_at TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (plan) REFERENCES plans (code) ON UPDATE CASCADE,
  FOREIGN KEY (shop_id) REFERENCES shops (id) ON DELETE CASCADE,
  CHECK (((provider IS NULL) OR ((length(provider) >= 1) AND (length(provider) <= 40)))),
  CHECK (((provider_customer_id IS NULL) OR (length(provider_customer_id) <= 200))),
  CHECK (((provider_subscription_id IS NULL) OR (length(provider_subscription_id) <= 200))),
  CHECK ((status IN ('trialing', 'active', 'past_due', 'canceled')))
) STRICT;
CREATE INDEX subscriptions_plan_idx ON subscriptions (plan);
CREATE UNIQUE INDEX subscriptions_provider_subscription_key ON subscriptions (provider, provider_subscription_id) WHERE (provider_subscription_id IS NOT NULL);
CREATE UNIQUE INDEX subscriptions_shop_id_key ON subscriptions (shop_id);
CREATE INDEX subscriptions_status_idx ON subscriptions (status);
CREATE TRIGGER subscriptions_set_updated_at AFTER UPDATE ON subscriptions FOR EACH ROW WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE subscriptions SET updated_at = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE rowid = NEW.rowid; END;

CREATE TABLE sync_failure_reports (
  shop_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  day TEXT NOT NULL,
  op_type TEXT NOT NULL,
  error_code TEXT NOT NULL,
  occurrences INTEGER NOT NULL DEFAULT 1,
  first_seen TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  last_seen TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (shop_id, user_id, day, op_type, error_code),
  FOREIGN KEY (shop_id) REFERENCES shops (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CHECK (((occurrences >= 1) AND (occurrences <= 1000000)))
) STRICT;
CREATE INDEX sync_failure_reports_day_idx ON sync_failure_reports (day);
CREATE INDEX sync_failure_reports_user_idx ON sync_failure_reports (user_id);

